import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"第 13 章 知识管理：让记忆可复用","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md"}'),d={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md"};function o(r,t,l,i,h,p){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-13-章-知识管理-让记忆可复用" tabindex="-1">第 13 章 知识管理：让记忆可复用 <a class="header-anchor" href="#第-13-章-知识管理-让记忆可复用" aria-label="Permalink to &quot;第 13 章 知识管理：让记忆可复用&quot;">​</a></h1><blockquote><p>本章目标：理解知识管理的三个层次（存→找→用）、掌握&quot;资料变知识&quot;的提炼方法，以及知识如何沉淀进记忆系统。<strong>知识管理不是整理文件，而是让过去的投入，在未来的任务里再次变现。</strong></p></blockquote><h2 id="_13-1-场景-收藏了-拥有了" tabindex="-1">13.1 场景：收藏了 ≠ 拥有了 <a class="header-anchor" href="#_13-1-场景-收藏了-拥有了" aria-label="Permalink to &quot;13.1 场景：收藏了 ≠ 拥有了&quot;">​</a></h2><p>你收集了很多资料：文章、笔记、代码片段、会议纪要。但&quot;收藏了 = 拥有了&quot;是错觉——真正的问题是：<strong>要用的时候，找不找得到、用不用得上。</strong></p><p>知识管理的目标不是&quot;存得多&quot;，而是<strong>让知识在需要时能被调出来、用起来</strong>。</p><h3 id="_13-1-1-知识管理失败的典型症状" tabindex="-1">13.1.1 知识管理失败的典型症状 <a class="header-anchor" href="#_13-1-1-知识管理失败的典型症状" aria-label="Permalink to &quot;13.1.1 知识管理失败的典型症状&quot;">​</a></h3><ul><li>资料越存越多，但要用时找不到；</li><li>找到了一堆，但不知道哪个最相关；</li><li>明明有现成的方法论，每次却从头开始想。</li></ul><h2 id="_13-2-知识管理的三个层次" tabindex="-1">13.2 知识管理的三个层次 <a class="header-anchor" href="#_13-2-知识管理的三个层次" aria-label="Permalink to &quot;13.2 知识管理的三个层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>问题</th><th>我的角色</th></tr></thead><tbody><tr><td><strong>存</strong></td><td>资料放哪、怎么命名</td><td>帮你建立可检索的结构</td></tr><tr><td><strong>找</strong></td><td>需要时能否快速找到</td><td>Glob/Grep 精准定位</td></tr><tr><td><strong>用</strong></td><td>找到后能否变成产出</td><td>提炼、总结、复用</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">核心认知</p><p><strong>三个层次的价值递增：存是基础，找是效率，用才是目的。</strong> 只存不用 = 数字囤积症；能找能用 = 真正的知识资产。</p></div><h2 id="_13-3-案例-把收藏夹变成知识库" tabindex="-1">13.3 案例：把收藏夹变成知识库 <a class="header-anchor" href="#_13-3-案例-把收藏夹变成知识库" aria-label="Permalink to &quot;13.3 案例：把收藏夹变成知识库&quot;">​</a></h2><h3 id="_13-3-1-指令" tabindex="-1">13.3.1 指令 <a class="header-anchor" href="#_13-3-1-指令" aria-label="Permalink to &quot;13.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我 docs/notes/ 里有一堆零散笔记，帮我：</span></span>
<span class="line"><span>1. 扫描并分类（按主题归入 ai/、marketing/、engineering/ 等）</span></span>
<span class="line"><span>2. 为每篇生成 3 行的摘要 + 标签（frontmatter）</span></span>
<span class="line"><span>3. 输出一份索引表 notes_index.md</span></span></code></pre></div><h3 id="_13-3-2-我的做法-逐步拆解" tabindex="-1">13.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_13-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;13.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Glob 列出全部笔记 → 统计数量、主题分布</span></span>
<span class="line"><span>② 提出分类方案（哪些笔记归哪类）→ 你确认</span></span>
<span class="line"><span>③ 逐篇 Read → 提炼 3 行摘要 + 标签</span></span>
<span class="line"><span>④ 摘要先给你抽查（质量如何？准确吗？）</span></span>
<span class="line"><span>⑤ 归类移动/复制 → 写 notes_index.md 索引</span></span>
<span class="line"><span>⑥ 交付：新目录结构 + 索引表</span></span></code></pre></div><h3 id="_13-3-3-摘要的黄金格式" tabindex="-1">13.3.3 摘要的黄金格式 <a class="header-anchor" href="#_13-3-3-摘要的黄金格式" aria-label="Permalink to &quot;13.3.3 摘要的黄金格式&quot;">​</a></h3><p><strong>一篇长文 → 一句话结论 + 3 个要点 + 适用范围 + 可执行动作</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：&quot;这篇文章讲结构化提示词</span></span>
<span class="line"><span>→ 结论：给 AI 任务要带验收标准</span></span>
<span class="line"><span>→ 要点：目标/输入/约束/验收</span></span>
<span class="line"><span>→ 适用：所有 AI 任务</span></span>
<span class="line"><span>→ 动作：用第 2 章模板&quot;</span></span></code></pre></div><p><strong>这样提炼出来的摘要，才是&quot;可用&quot;的知识，而不是一段压缩的文字。</strong></p><h2 id="_13-4-提炼-从资料到知识" tabindex="-1">13.4 提炼：从资料到知识 <a class="header-anchor" href="#_13-4-提炼-从资料到知识" aria-label="Permalink to &quot;13.4 提炼：从资料到知识&quot;">​</a></h2><h3 id="_13-4-1-提炼四步法" tabindex="-1">13.4.1 提炼四步法 <a class="header-anchor" href="#_13-4-1-提炼四步法" aria-label="Permalink to &quot;13.4.1 提炼四步法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>问题</th><th>产出</th></tr></thead><tbody><tr><td>结论</td><td>这篇文章到底说了什么？</td><td>一句话</td></tr><tr><td>要点</td><td>哪几个点支撑结论？</td><td>3 条要点</td></tr><tr><td>适用</td><td>什么场景能用上？</td><td>适用边界</td></tr><tr><td>动作</td><td>我下一步做什么？</td><td>可执行动作</td></tr></tbody></table><h3 id="_13-4-2-资料-vs-知识的区别" tabindex="-1">13.4.2 资料 vs 知识的区别 <a class="header-anchor" href="#_13-4-2-资料-vs-知识的区别" aria-label="Permalink to &quot;13.4.2 资料 vs 知识的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>资料</th><th>知识</th></tr></thead><tbody><tr><td>形态</td><td>原文、全文</td><td>提炼后的要点</td></tr><tr><td>价值</td><td>需要时再去读</td><td>直接可执行</td></tr><tr><td>例子</td><td>存了一篇《提示词指南》</td><td>&quot;给 AI 任务要带验收标准&quot;</td></tr></tbody></table><h2 id="_13-5-让知识-长-进记忆" tabindex="-1">13.5 让知识&quot;长&quot;进记忆 <a class="header-anchor" href="#_13-5-让知识-长-进记忆" aria-label="Permalink to &quot;13.5 让知识&quot;长&quot;进记忆&quot;">​</a></h2><h3 id="_13-5-1-记忆-vs-文件的分工" tabindex="-1">13.5.1 记忆 vs 文件的分工 <a class="header-anchor" href="#_13-5-1-记忆-vs-文件的分工" aria-label="Permalink to &quot;13.5.1 记忆 vs 文件的分工&quot;">​</a></h3><p>稳定的知识（你的方法论、常用模板、项目决策）应该<strong>进入记忆系统</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;把这个提示词模板存进记忆，以后写方案默认用它。&quot;</span></span></code></pre></div><p>而具体的资料文件留在项目里。这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记忆 = 方法论（怎么做）</span></span>
<span class="line"><span>文件 = 素材库（有什么）</span></span></code></pre></div><h3 id="_13-5-2-什么知识该进记忆" tabindex="-1">13.5.2 什么知识该进记忆 <a class="header-anchor" href="#_13-5-2-什么知识该进记忆" aria-label="Permalink to &quot;13.5.2 什么知识该进记忆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>该进记忆</th><th>不该进记忆</th></tr></thead><tbody><tr><td>稳定的方法论、偏好</td><td>一次性的临时资料</td></tr><tr><td>常用模板、写作风格</td><td>会变化的原始数据</td></tr><tr><td>项目关键决策、术语表</td><td>敏感信息（密钥/密码）</td></tr></tbody></table><h2 id="_13-6-知识管理的红线" tabindex="-1">13.6 知识管理的红线 <a class="header-anchor" href="#_13-6-知识管理的红线" aria-label="Permalink to &quot;13.6 知识管理的红线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>红线</th><th>说明</th></tr></thead><tbody><tr><td><strong>先确认再入库</strong></td><td>摘要、分类、标签先给你看</td></tr><tr><td><strong>不破坏原文件</strong></td><td>归类用复制或移动前先确认</td></tr><tr><td><strong>敏感资料标注</strong></td><td>涉及隐私/机密的资料，明确访问范围</td></tr></tbody></table><h2 id="_13-7-知识管理的进阶-从个人到团队" tabindex="-1">13.7 知识管理的进阶：从个人到团队 <a class="header-anchor" href="#_13-7-知识管理的进阶-从个人到团队" aria-label="Permalink to &quot;13.7 知识管理的进阶：从个人到团队&quot;">​</a></h2><p>知识管理不止于个人：</p><table tabindex="0"><thead><tr><th>层次</th><th>说明</th><th>参考章节</th></tr></thead><tbody><tr><td>个人知识库</td><td>你的笔记、方法论</td><td>本章</td></tr><tr><td>项目知识库</td><td>项目文档、决策记录</td><td>第 20 章</td></tr><tr><td>团队知识库</td><td>团队共享的 Skill 与方法论</td><td>第 16、17 章</td></tr></tbody></table><p><strong>个人积累 → 项目沉淀 → 团队复用</strong>，是知识管理价值的完整放大链。</p><h2 id="_13-8-练习" tabindex="-1">13.8 练习 <a class="header-anchor" href="#_13-8-练习" aria-label="Permalink to &quot;13.8 练习&quot;">​</a></h2><ol><li>给我一个装满资料的目录，让我做&quot;分类 + 摘要 + 索引&quot;；</li><li>抽查 3 篇摘要，反馈我提炼得准不准（用 13.4 的四步法对照）；</li><li>把其中一条方法论存入记忆；</li><li>设计你的知识库目录结构，让我帮你落地。</li></ol><hr><blockquote><p>小结：知识管理不是整理文件，而是<strong>让过去的投入，在未来的任务里再次变现</strong>。存 → 找 → 用，三个层次缺一不可；提炼四步法（结论/要点/适用/动作）是核心动作。下一章：信息调研。</p></blockquote>`,42)])])}const u=a(d,[["render",o]]);export{b as __pageData,u as default};
